<?php
require 'config.php'; require 'auth.php'; requireLogin(); $pageTitle='Stok Keluar'; $items=read_data('items'); usort($items,fn($a,$b)=>strcmp($a['name'],$b['name'])); $selectedId=(int)($_GET['item_id']??0); $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){ $itemId=(int)($_POST['item_id']??0); $qty=(int)($_POST['quantity']??0); $note=trim($_POST['note']??''); $selectedId=$itemId; $date=trim($_POST['tx_date']??''); $date=$date?str_replace('T',' ',$date).':00':date('Y-m-d H:i:s'); $all=read_data('items'); $idx=find_index($all,$itemId); if($idx===null||$qty<=0)$errors[]='Pilih alat dan masukkan jumlah yang valid.'; elseif($qty>$all[$idx]['stock'])$errors[]='Jumlah keluar melebihi stok yang tersedia.'; else { $all[$idx]['stock']-=$qty; write_data('items',$all); save_transaction($itemId,'OUT',$qty,$note,$date); $_SESSION['flash']=['type'=>'success','message'=>'Stok keluar berhasil dicatat.']; redirect('index.php'); }} include 'header.php'; ?>
<section class="page-heading"><div><h1>Catat Stok Keluar</h1><p>Kurangi stok dan simpan riwayat otomatis.</p></div></section><div class="form-card"><?php foreach($errors as $e1): ?><div class="alert alert-error"><?= e($e1) ?></div><?php endforeach; ?><form method="post"><div class="form-group"><label>Alat</label><select name="item_id" required><option value="">Pilih alat</option><?php foreach($items as $i): ?><option value="<?= $i['id'] ?>" <?= $i['id']==$selectedId?'selected':'' ?>><?= e($i['sku'].' - '.$i['name']) ?> (<?= $i['stock'].' '.e($i['unit']) ?>)</option><?php endforeach; ?></select></div><div class="form-group"><label>Jumlah Keluar</label><input type="number" name="quantity" min="1" required></div><div class="form-group"><label>Tanggal & Jam</label><input type="datetime-local" name="tx_date" value="<?= date('Y-m-d\TH:i') ?>" required></div><div class="form-group"><label>Catatan</label><input name="note" list="note-out-list" placeholder="Contoh: Pemasangan baru"><datalist id="note-out-list"><option value="Pemasangan baru"><option value="Perbaikan/maintenance"><option value="Alat rusak"><option value="Transfer ke gudang lain"></datalist></div><div class="form-actions"><button class="btn btn-danger">Simpan Stok Keluar</button><a href="index.php" class="btn btn-secondary">Batal</a></div></form></div><?php include 'footer.php'; ?>